import { useRef, useEffect, useState } from "react";
import L from "leaflet";
import { MAP_ZOOM_LIMITS } from "../constants/mapConfig";

export const useMap = () => {
  const mapRef = useRef(null);
  const mapInstanceRef = useRef(null);
  const [isMapReady, setIsMapReady] = useState(false);

  const initializeMap = (bounds) => {
    if (!mapRef.current) {
      console.error("Contenedor del mapa no encontrado");
      return null;
    }

    if (mapInstanceRef.current) {
      return mapInstanceRef.current;
    }

    try {
      // ✅ CALCULAR CORRECTAMENTE el centro
      const centerLat = (bounds[0][0] + bounds[1][0]) / 2;
      const centerLng = (bounds[0][1] + bounds[1][1]) / 2;

      console.log("🗺️ Inicializando mapa:", {
        center: [centerLat, centerLng],
        bounds: bounds,
        zoom: MAP_ZOOM_LIMITS.default,
      });

      const map = L.map(mapRef.current, {
        center: [centerLat, centerLng],
        zoom: MAP_ZOOM_LIMITS.default,
        minZoom: 15, // ✅ Más flexible
        maxZoom: 20, // ✅ Más flexible
        zoomControl: true, // ✅ Permitir control de zoom
        attributionControl: true,
      });

      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
        attribution: "© OpenStreetMap contributors",
        minZoom: 15,
        maxZoom: 20,
      }).addTo(map);

      // ✅ AJUSTAR AL BOUNDS INICIALMENTE - ESTO ES CLAVE
      setTimeout(() => {
        map.fitBounds(bounds, {
          padding: [20, 20],
          maxZoom: 17, // ✅ Evitar zoom excesivo
        });
        console.log("📍 Mapa ajustado a bounds:", bounds);
      }, 100);

      // ✅ ESTABLECER LÍMITES DE MOVIMIENTO
      map.setMaxBounds([
        [bounds[0][0] - 0.002, bounds[0][1] - 0.002], // SW extendido
        [bounds[1][0] + 0.002, bounds[1][1] + 0.002], // NE extendido
      ]);

      console.log("📍 Límites establecidos:", map.getMaxBounds());

      // ✅ EVENTOS PARA MANTENER DENTRO DE LOS LÍMITES
      map.on("drag", function () {
        map.panInsideBounds(bounds, { animate: false });
      });

      // ✅ EVENTO PARA DEBUG
      map.on("load", function () {
        console.log("✅ Mapa cargado completamente");
        console.log("📊 Estado final:", {
          center: map.getCenter(),
          zoom: map.getZoom(),
          bounds: map.getBounds(),
        });
      });

      // ✅ EVENTO CUANDO TERMINA EL FITBOUNDS
      map.on("moveend", function () {
        console.log("🎯 Mapa movido - Zoom actual:", map.getZoom());
      });

      mapInstanceRef.current = map;
      setIsMapReady(true);

      // ✅ FORZAR REDIMENSIONADO
      setTimeout(() => {
        map.invalidateSize();
        console.log("🔄 Mapa redimensionado");
      }, 300);

      return map;
    } catch (error) {
      console.error("❌ Error inicializando mapa:", error);
      return null;
    }
  };

  // ✅ FUNCIÓN PARA REAJUSTAR EL MAPA A LOS BOUNDS
  const fitToBounds = (bounds) => {
    if (mapInstanceRef.current && bounds) {
      mapInstanceRef.current.fitBounds(bounds, {
        padding: [20, 20],
        maxZoom: 18,
      });
    }
  };

  useEffect(() => {
    return () => {
      if (mapInstanceRef.current) {
        mapInstanceRef.current.remove();
        mapInstanceRef.current = null;
        setIsMapReady(false);
      }
    };
  }, []);

  return {
    mapRef,
    initializeMap,
    mapInstance: mapInstanceRef.current,
    isMapReady,
    fitToBounds, // ✅ Exportar función para reajustar
  };
};
